class SessionStore(SessionBase):
    def load(self):
        try:
            session_data = self.decode(self._session_key)
            return self._legacy_decode(session_data)
        except Exception as e:
            print("Exception in session loading:", e)
            raise

    def decode(self, session_data):
        try:
