                order = Order()
                order.product = Product()
                order.product.sku = "foo"
                order.product.save()
                order.save()
                if Order.objects.filter(product_id="").exists():
                    print("Issue reproduced")
                else:
                    print("Issue resolved")
        except Exception as e:
            print("Other issues:", e)
            return

