from django.test import TestCase
from django.db import connections
from django.db.utils import ProgrammingError
from django.conf import settings
from django.test.utils import override_settings

# Define router
class Router:
    def allow_migrate(self, db, app_label, model_name=None, **hints):
        if db == 'default':
            return True
        return False

# Override settings
@override_settings(
    DATABASE_ROUTERS=['__main__.Router'],
    DATABASES={
        'default': {
            'ENGINE': 'django.db.backends.sqlite3',
            'NAME': ':memory:',
        },
        'other': {
            'ENGINE': 'django.db.backends.sqlite3',
            'NAME': ':memory:',
        },
    },
)
class MigrationRecorderRouterIssueTest(TestCase):
    databases = '__all__'

    def test_migration_recorder_obeys_router(self):
        connection_default = connections['default']
        connection_other = connections['other']

        with connection_default.schema_editor() as schema_editor:
            schema_editor.create_model(self.get_migration_model())

        try:
            with connection_other.schema_editor() as schema_editor:
                schema_editor.create_model(self.get_migration_model())
            print("Issue reproduced")
        except ProgrammingError:
            print("Issue resolved")
        except Exception:
            print("Other issues")

    def get_migration_model(self):
        from django.db import models, router

        class Migration(models.Model):
            app = models.CharField(max_length=255)
            name = models.CharField(max_length=255)

            class Meta:
                app_label = 'migrations'
                managed = False

            def save(self, *args, **kwargs):
                if not router.allow_migrate(self._state.db, self._meta.app_label):
                    raise ProgrammingError(f"Cannot migrate on database: {self._state.db}")
                super().save(*args, **kwargs)

        return Migration

# Run the test
MigrationRecorderRouterIssueTest('test_migration_recorder_obeys_router').run()
